(* [comment removed for export] *)
Ltac amem := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => mm end.

(* [comment removed for export] *)
Ltac ro_debruijn MI :=
  let mm := amem in
  let bs := eval vm_compute in (option.default [] (image_bytes asegs 0x10420 8)) in
  assert (RC1 : ro_cells asegs mm 0x10420 [CB (length bs) bs])
    by (apply ro_cells_image; [exact MI| vm_compute; reflexivity| lia| cbn; lia]);
  let bs := eval vm_compute in (option.default [] (image_bytes asegs 0x104a0 64)) in
  assert (RC2 : ro_cells asegs mm 0x104a0 [CB (length bs) bs])
    by (apply ro_cells_image; [exact MI| vm_compute; reflexivity| lia| cbn; lia]);
  cbn [length] in RC1, RC2.

(* [comment removed for export] *)
Ltac fold_reg k := let e := getreg k in lazymatch e with Z_to_bv 64 ?x => let v := eval vm_compute in x in change x with v end.

(* [comment removed for export] *)
